import {validateUnitHistory,validateUnitControllerDelta,CONTROLLER_PATHS} from './unit-recovery.mjs';
const clone=x=>structuredClone(x),seal=p=>{const {fingerprint,...b}=p;return {...b,fingerprint:hash(b)};};
function fixture(){
 const f=missingUnitFixture({clock:Date.now()}),q=f.proof,controller=q.freshPlan.controller;
 const plan=seal({...f.sourcePlan,sha:c.source,controller:c.controller,migrationBase:c.baseline}),freshPlan=seal({...plan,controller}),priorPlan=seal({...plan,sha:c.expectationSource,controller:c.expectationController});
 Object.assign(f.run,{id:c.runId,head_sha:c.controller,head_branch:'main'});
 for(const j of f.jobs){Object.assign(j,{run_id:c.runId,head_sha:c.controller,head_branch:'main'});if(j.name==='runner-diagnostics')j.conclusion='skipped';if(j.name===`test (${c.unit})`){j.id=c.jobId;j.steps.push({name:'Run actions/upload-artifact@pinned',status:'pending',conclusion:null});}}
 for(const [i,a]of f.artifacts.entries())Object.assign(a,{id:5000+i,digest:'sha256:'+'c'.repeat(64)});
 Object.assign(q,{freshPlan});Object.assign(q.report,{sha:c.source,fingerprint:freshPlan.fingerprint});Object.assign(q.font,{candidate:c.source,controller});q.expected.after=f.run.updated_at;q.fileBlob={original:c.testBlob,candidate:c.testBlob,expectation:c.testBlob};
 Object.assign(q.expectation.plan,priorPlan);Object.assign(q.expectation.report,{sha:c.expectationSource,fingerprint:priorPlan.fingerprint});Object.assign(q.expectation.selection,{runId:c.expectationRunId,source:c.expectationSource,controller:c.expectationController,branch:'main'});
 Object.assign(q.expectation.metadata.run,{id:c.expectationRunId,head_sha:c.expectationController,head_branch:'main',conclusion:'failure'});
 const priorJob=q.expectation.metadata.jobs[0];Object.assign(priorJob,{run_id:c.expectationRunId,head_sha:c.expectationController,head_branch:'main'});
 Object.assign(q.expectation.metadata.artifacts[0].workflow_run,{id:c.expectationRunId,head_sha:c.expectationController,head_branch:'main'});Object.assign(q.expectation.source,{runId:c.expectationRunId,controller:c.expectationController,branch:'main'});
 const producer=q.producer,font=producer.steps[0];font.number=8;producer.steps.push({name:'Bounded source-owned native PostgreSQL image transport',number:7,conclusion:'success',started_at:producer.started_at,completed_at:new Date(Date.parse(producer.started_at)+250).toISOString()});
 q.metadata.jobs.find(j=>j.name==='deployment-hold').steps.push({name:'Deployment remains disabled',conclusion:'success'});
 const start=Date.parse(producer.started_at),at=n=>new Date(start+n).toISOString();
 q.nativePrepull={kind:'BOUNDED_SOURCE_NATIVE_POSTGRES_PREPULL_NOT_TEST_PASS',releaseAuthorized:false,source:c.source,controller,runId:q.run.id,attempt:1,unit:c.unit,owner:{path:'.github/ci/postgres.sh',gitBlob:'49d3fe2671ca6f13192169d8101c2c14f62236fc',sha256:'e14ab0a207112c61d40b7801c0b1272ed20eb0aca0042d56c8a4cc7e572e52d0',image:NATIVE_POSTGRES_IMAGE},timeoutMs:180000,pullAttempts:1,startedAt:at(100),endedAt:at(200),pull:{status:0,signal:null,errorCode:null,timedOut:false,elapsedMs:100},inspect:{status:0,signal:null,errorCode:null,configId:'sha256:'+'9'.repeat(64),repoDigests:[NATIVE_POSTGRES_IMAGE.replace('postgres:16@','postgres@')],os:'linux',architecture:'amd64'}};
 const reports=plan.units.filter(u=>u.id!==c.unit).map(u=>({schemaVersion:1,id:u.id,sha:c.source,fingerprint:plan.fingerprint,cwd:'/candidate',files:u.files,exitCode:0,batches:[{exitCode:0,result:{success:true,numTotalTests:u.files.length,numPassedTests:u.files.length,numFailedTests:0,numFailedTestSuites:0,testResults:u.files.map(p=>({name:'/candidate/'+p,status:'passed',assertionResults:[{status:'passed',fullName:'retained '+p}]}))}}]}));
 const diagnostic={controller,runId:300};return {plan,freshPlan,source:{run:f.run,jobs:f.jobs,artifacts:f.artifacts},reports,missingProof:{proof:q,producerDiagnostic:diagnostic},verificationController:controller,verificationDiagnostic:diagnostic,reviewedController:controller};
}
test('exact-source certificate retains cancelled original, untouched policy/build identity and all other native evidence',()=>{const f=fixture(),cert=verifyUnitRecovery(f);assert.equal(cert.bindingVersion,UNIT_RECOVERY_BINDING);assert.equal(cert.recoveryPolicy,UNIT_RECOVERY_POLICY);assert.equal(cert.sha,c.source);assert.equal(cert.controller,c.controller);assert.equal(cert.runId,c.runId);assert.equal(cert.originalConclusion,'cancelled');assert.equal(cert.policyVersion,f.plan.policyVersion);assert.equal(cert.units.filter(u=>u.kind==='retained').length,f.plan.units.length-1);assert.equal(cert.units.find(u=>u.kind==='complete-unit-recovery').priorExpectationUsedAsPass,false);assert.equal(cert.originalInterruptedJob.steps.find(s=>s.name.includes('run-unit')).conclusion,null);assert(cert.originalDependentJobs.every(j=>j.observation==='NOT_PRESENT_IN_TERMINAL_API_INVENTORY'));assert.equal(cert.releaseAuthorized,false);assert(!Object.hasOwn(cert,'setupFailure'));});
for(const [name,edit]of [['different source',f=>f.plan.sha='a'.repeat(40)],['different run',f=>f.source.run.id=1],['pending run',f=>f.source.run.status='in_progress'],['fake original success',f=>f.source.run.conclusion='success'],['other failed native unit',f=>f.source.jobs.find(j=>j.name.startsWith('browser')).conclusion='failure'],['compiler failed',f=>f.source.jobs.find(j=>j.name==='typecheck').conclusion='failure'],['build failed',f=>f.source.jobs.find(j=>j.name==='build').conclusion='failure'],['original process claimed PASS',f=>f.source.jobs.find(j=>j.id===c.jobId).steps[2].conclusion='success'],['fabricated original report',f=>f.source.artifacts.push({name:'unit-'+c.unit})],['verify actually failed',f=>f.source.jobs.push({...f.source.jobs[0],id:999,name:'verify',conclusion:'failure'})],['retained report missing',f=>f.reports.pop()],['retained report duplicate',f=>f.reports[1]=f.reports[0]],['retained failed case',f=>f.reports[0].exitCode=1],['fresh case renamed',f=>f.missingProof.proof.report.batches[0].result.testResults[0].assertionResults[0].fullName='renamed'],['fresh runtime drift',f=>f.missingProof.proof.freshPlan.execution.workers=1],['fresh fonts failed',f=>f.missingProof.proof.font.steps[0].status=1],['fresh PG drift',f=>f.missingProof.proof.report.databaseTerminalEvidence.settings.jit='off'],['pull timeout',f=>f.missingProof.proof.nativePrepull.pull.status=124],['pull owner relabel',f=>f.missingProof.proof.nativePrepull.owner.gitBlob='b'.repeat(40)],['pull receipt missing',f=>delete f.missingProof.proof.nativePrepull],['deployment enabled',f=>f.missingProof.proof.metadata.jobs.find(j=>j.name==='deployment-hold').steps=[]],['prior case failed',f=>f.missingProof.proof.expectation.report.exitCode=1],['foreign expectation',f=>f.missingProof.proof.expectation.selection.source=c.source],['unreviewed controller',f=>f.reviewedController=null]])test('v2 refuses '+name,()=>{const f=fixture();edit(f);assert.throws(()=>verifyUnitRecovery(f));});
test('exact request refuses another source/run/unit and any mixed gate mode',()=>{const x={missing_unit:c.unit,missing_original_run:String(c.runId),expected_sha:c.source,candidate_ref:'codex/source'};validateUnitRecoveryRequest(x,'workflow_dispatch');for(const edit of [{expected_sha:c.expectationSource},{missing_original_run:'1'},{missing_unit:'db-'+'0'.repeat(16)},{build_only:true},{diagnostics_only:true}])assert.throws(()=>validateUnitRecoveryRequest({...x,...edit},'workflow_dispatch'));});
test('history admits only actual replacement plus explicit qualified controller; no stale failed-font allowance',()=>{const f=fixture(),run={id:200,display_title:`Missing whole unit · ${c.unit} · codex/source`,status:'completed',conclusion:'success',run_attempt:1,head_sha:f.verificationController,created_at:f.missingProof.proof.run.created_at,updated_at:f.missingProof.proof.run.updated_at};const args={source:f.source,rows:[run],candidateBranch:'codex/source',unitRunId:200,controllerDiagnostics:[300]};const h=validateUnitHistory(args);assert.equal(h.executions.length,1);for(const edit of [r=>r.conclusion='failure',r=>r.status='in_progress',r=>r.id=44449576117]){const bad=clone(args);edit(bad.rows[0]);assert.throws(()=>validateUnitHistory(bad));}validateUnitControllerDelta([...CONTROLLER_PATHS]);assert.throws(()=>validateUnitControllerDelta([...CONTROLLER_PATHS,'core/payroll.ts']));});
test('grant consumer refuses malformed/rebound/dropped original coverage under a recomputed certificate hash',()=>{
 const f=fixture(),cert=verifyUnitRecovery(f),replacement=cert.units.find(u=>u.kind==='complete-unit-recovery');
 // Consumer-only synthetic certificate fixture. Actual assembler above independently verifies every raw report.
 cert.units=[replacement,...Array.from({length:100},(_,i)=>({id:'retained-fixture-'+i,kind:'retained',tests:i===0?55095:1,reportHash:'a'.repeat(64),source:{runId:c.runId,jobId:6000+i,artifactId:7000+i,digest:'sha256:'+'b'.repeat(64)}}))];
 Object.assign(cert,{sourceFingerprint:'4b79e6d71ec9e215c02b0132736b9227c46243245484ada91ac448dd1c709cc1',suiteFiles:4290,browserFiles:126,tests:55195,history:{sourceRunId:c.runId}});
 const wrap=c=>({...c,recovery:c,controllerBranch:'main',fingerprint:hash(c)}),evidence=wrap(cert);validateUnitRecoveryGrantEvidence(evidence,f.source.run);
 for(const edit of [c=>c.bindingVersion='old',c=>c.originalReportAbsent=false,c=>c.originalConclusion='success',c=>c.controller='e'.repeat(40),c=>c.baseline='e'.repeat(40),c=>c.units.pop(),c=>c.units[2].source.jobId=c.units[1].source.jobId,c=>c.originalDependentJobs[1].name='verify',c=>c.tests--,c=>c.sourceFingerprint='a'.repeat(64)]){const bad=clone(cert);edit(bad);assert.throws(()=>validateUnitRecoveryGrantEvidence(wrap(bad),f.source.run));}
 assert.throws(()=>validateUnitRecoveryGrantEvidence({...evidence,controllerBranch:'codex/other'},f.source.run));
 const i=installationFixture(),input={...i,evidence:{...i.evidence,...evidence,result:'PASS',tier:'ci',build:{...i.evidence.build,source:c.source,controller:c.controller,runId:c.runId}},run:{...i.run,...f.source.run},producer:{...i.producer,run_id:c.runId,head_sha:c.controller,started_at:new Date(Date.parse(f.source.run.created_at)+60000).toISOString(),completed_at:new Date(Date.parse(f.source.run.updated_at)-60000).toISOString()}};
 const grant=createInstallGrant(input);assert.equal(grant.format,2);assert.equal(grant.source,c.source);assert.equal(grant.controller,c.controller);assert.equal(grant.runId,c.runId);assert.equal(grant.build.nextBuildId,i.evidence.build.nextBuildId);assert.equal(grant.witnessFingerprint,hash(cert));assert(!Object.hasOwn(grant,'recovery'));validateInstallGrant(grant);
 assert.throws(()=>createInstallGrant({...input,evidence:{...input.evidence,controller:f.verificationController}}));
 const s=readFileSync(new URL('./ci-install-grant.mjs',import.meta.url),'utf8');assert(s.includes('unitRecovered?evidence.recovery.originalConclusion'));
});

test('dedicated controller admits only exact controller qualification or exact 825 missing-unit mode; FULL cannot start',()=>{
 const controller='e'.repeat(40),ref='refs/heads/'+UNIT_RECOVERY_CONTROLLER_BRANCH;
 const env={GITHUB_ACTIONS:'true',CI:'true',RUNNER_ENVIRONMENT:'github-hosted',GITHUB_JOB:'resolve',GITHUB_EVENT_NAME:'workflow_dispatch',GITHUB_RUN_ATTEMPT:'1',GITHUB_REPOSITORY:'StradaverseHub/ai-hr',GITHUB_REPOSITORY_ID:'1333414856',GITHUB_REF:ref,GITHUB_WORKFLOW_REF:'StradaverseHub/ai-hr/.github/workflows/alpha-staging.yml@'+ref,GITHUB_SHA:controller,AIHR_CI_CONTROL_HEAD:controller};
 const event={ref,repository:{full_name:'StradaverseHub/ai-hr',id:1333414856},inputs:{candidate_ref:UNIT_RECOVERY_CONTROLLER_BRANCH,expected_sha:controller,migration_base:c.baseline,test_parallelism:'48',diagnostics_only:'true',controller_only:'true',build_only:'false',missing_unit:'',missing_original_run:''}};
 assert.equal(validateDedicatedUnitControllerRequest(env,event),'controller-only');assert.equal(validateDedicatedUnitControllerRequest(env,{...event,ref:UNIT_RECOVERY_CONTROLLER_BRANCH}),'controller-only');
 const producer=clone(event);Object.assign(producer.inputs,{candidate_ref:'codex/board-final-fixture-repairs-20261119',expected_sha:c.source,diagnostics_only:'false',controller_only:'false',missing_unit:c.unit,missing_original_run:String(c.runId)});assert.equal(validateDedicatedUnitControllerRequest(env,producer),'missing-unit');
 for(const patch of [{missing_unit:''},{missing_original_run:''},{expected_sha:c.expectationSource},{build_only:'true'},{diagnostics_only:'true'},{candidate_ref:'main'},{unknown_mode:'true'},{test_parallelism:'4'}])assert.throws(()=>validateDedicatedUnitControllerRequest(env,{...producer,inputs:{...producer.inputs,...patch}}));
 const full=clone(producer);Object.assign(full.inputs,{missing_unit:'',missing_original_run:''});assert.throws(()=>validateDedicatedUnitControllerRequest(env,full));assert.throws(()=>validateDedicatedUnitControllerRequest({...env,GITHUB_EVENT_NAME:'push'},event));assert.throws(()=>validateDedicatedUnitControllerRequest({...env,GITHUB_REF:'refs/heads/main'},event));
 const workflow=readFileSync(new URL('../workflows/alpha-staging.yml',import.meta.url),'utf8');assert(workflow.indexOf('validateDedicatedUnitControllerRequest(process.env')<workflow.indexOf('CI integrity regression checks'));
});
